import { defaultBackend } from './backends';
import { AlgoliaBackend } from './backends/algolia';
import { db } from './db';
import { getId } from './id';

let isAlgolia = defaultBackend instanceof AlgoliaBackend;

if (isAlgolia) {
  await db.backend.upsert({
    where: { identifier: 'algolia' },
    create: {
      ...getId('backend'),
      isDefault: true,
      identifier: 'algolia',
      name: 'Algolia',
      id: 'algolia'
    },
    update: { isDefault: true }
  });

  await db.backend.updateMany({
    where: { identifier: { not: 'algolia' } },
    data: { isDefault: false }
  });
}

export let backend = await db.backend.upsert({
  where: { identifier: 'pg' },
  create: {
    ...getId('backend'),
    isDefault: !isAlgolia,
    identifier: 'pg',
    name: 'PostgreSQL',
    id: 'pg'
  },
  update: {
    isDefault: !isAlgolia
  }
});

import { RedisClient } from 'bun';
import { VoyagerApi } from './controllers';
import { db } from './db';

let server = Bun.serve({
  fetch: VoyagerApi,
  port: 52060
});

console.log(`Service running on http://localhost:${server.port}`);

let redis = new RedisClient(process.env.REDIS_URL?.replace('rediss://', 'redis://'), {
  tls: process.env.REDIS_URL?.startsWith('rediss://')
});

Bun.serve({
  fetch: async _ => {
    try {
      await db.backend.count();

      await redis.ping();

      return new Response('OK');
    } catch (e) {
      return new Response('Service Unavailable', { status: 503 });
    }
  },
  port: 12121
});
